using System;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.SceneManagement;
using ParkingLotEnvironment.CloudPilot.Integrated;
namespace ParkingLotEnvironment.CloudPilot {
public static class TrainingLotRunnerV2 {
 const string Source="Assets/_Parkside/Scenes/ParklingLot.unity",W="Assets/ParkingLotEnvironment/CloudPilot/ParkingTraining20261104/Revision2",Trial=W+"/TrainingLotV2.unity",Expected="e75f1e1537db60586481e853c4f512927b7c66da3062eaf89f3c2f0989f542f8";
 static string output,trialHash;static GameObject root;static Camera cam;static int frame=-2;static Vector3 position;static Quaternion rotation;static double started;
 static string Hash(string p){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
 static void Check(){if(File.Exists("/workspaces/parkside-setup/STOP")||Hash(Source)!=Expected)throw new Exception("STOP or source changed");}
 static void Args(){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-collabOutput");if(i<0)throw new Exception("Output required");output=Path.GetFullPath(args[i+1]);Directory.CreateDirectory(output);}
 public static void BuildAndBake(){try{Check();Args();if(File.Exists(Trial))throw new Exception("Candidate exists");EditorSceneManager.OpenScene(Source);var scene=SceneManager.GetActiveScene();root=scene.GetRootGameObjects().Single(g=>g.name=="ParkingLot_CornerPilot_Root");TrainingBuilderV2.Apply(root,output);TrainingValidation.Check(root,output);var probe=root.GetComponentsInChildren<ReflectionProbe>(true).First();probe.enabled=false;probe.boxProjection=true;probe.transform.position=new Vector3(0,2,-3);probe.center=Vector3.zero;probe.size=new Vector3(36,14,44);var settings=UnityEngine.Object.Instantiate(Lightmapping.lightingSettings);settings.autoGenerate=false;AssetDatabase.CreateAsset(settings,W+"/TrainingLighting.lighting");Lightmapping.lightingSettings=settings;AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene,Trial))throw new Exception("Save failed");started=EditorApplication.timeSinceStartup;EditorApplication.update+=BakeTick;if(!Lightmapping.BakeAsync())throw new Exception("Bake rejected");}catch(Exception e){Fail(e);}}
 static void BakeTick(){try{Check();double elapsed=EditorApplication.timeSinceStartup-started;if(elapsed>1200){Lightmapping.Cancel();throw new Exception("Bake timeout");}if(elapsed<5||Lightmapping.isRunning)return;EditorApplication.update-=BakeTick;if(LightmapSettings.lightmaps.Length<1)throw new Exception("No baked lightmaps");var p=root.GetComponentsInChildren<ReflectionProbe>(true).First();p.enabled=true;p.mode=ReflectionProbeMode.Baked;p.timeSlicingMode=ReflectionProbeTimeSlicingMode.NoTimeSlicing;string path=W+"/TrainingReflection.exr";if(!Lightmapping.BakeReflectionProbe(p,path))throw new Exception("Probe bake failed");AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);p.mode=ReflectionProbeMode.Custom;p.customBakedTexture=AssetDatabase.LoadAssetAtPath<Texture>(path);if(!p.customBakedTexture||!p.boxProjection)throw new Exception("Missing box projected reflection");EditorUtility.SetDirty(p);EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());if(!EditorSceneManager.SaveScene(SceneManager.GetActiveScene()))throw new Exception("Save failed");Check();File.WriteAllText(output+"/bake-info.txt","Bake seconds="+elapsed+"; candidate SHA="+Hash(Trial)+"; lightmaps="+LightmapSettings.lightmaps.Length+"; box projection="+p.boxProjection+"; reflection="+path+"\n");EditorApplication.Exit(0);}catch(Exception e){Fail(e);}}
 public static void Capture(){try{Check();Args();trialHash=Hash(Trial);EditorSceneManager.OpenScene(Trial);root=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name=="ParkingLot_CornerPilot_Root");TrainingValidation.Check(root,output);cam=root.GetComponentInChildren<Camera>();var fx=cam.GetComponent<ParkingLotIntegratedPhotoFinish>();if(!fx||!fx.enabled||LightmapSettings.lightmaps.Length<1)throw new Exception("Missing camera effect or lightmap");position=cam.transform.position;rotation=cam.transform.rotation;cam.enabled=false;EditorApplication.update+=CaptureTick;}catch(Exception e){Fail(e);}}
 static void CaptureTick(){try{Check();if(frame<0)Render(null,position,rotation,960,540);else if(frame==0)Render("eye.png",position,rotation,1920,1080);else if(frame==1)Render("close-car.png",new Vector3(1.5f,1.8f,-16),Quaternion.Euler(3,-12,0),1920,1080);else if(frame==2)Render("side3m.png",position+Vector3.right*3,rotation,1920,1080);else if(frame==3)Render("third-person.png",new Vector3(1.5f,2.2f,-17),Quaternion.LookRotation(new Vector3(4.8f,-1.2f,7.2f)),1920,1080);else if(frame==4)Render("aerial.png",new Vector3(23,29,-31),Quaternion.LookRotation(new Vector3(-23,-28,28)),1920,1080);else{EditorApplication.update-=CaptureTick;var fx=cam.GetComponent<ParkingLotIntegratedPhotoFinish>();if(Hash(Trial)!=trialHash||!fx.lastAppliedCorrectly||!fx.lastRestoredCorrectly)throw new Exception("Scene changed or shadow state not restored");File.WriteAllText(output+"/capture-complete.txt","Reopened baked candidate; 1080p eye, close-car, side3m, aerial. Candidate SHA="+trialHash+"\n");EditorApplication.Exit(0);return;}frame++;}catch(Exception e){Fail(e);}}
 static void Render(string name,Vector3 p,Quaternion q,int w,int h){var rt=new RenderTexture(w,h,24,RenderTextureFormat.ARGBHalf);var pic=new Texture2D(w,h,TextureFormat.RGB24,false);var prev=RenderTexture.active;var target=cam.targetTexture;try{rt.Create();cam.targetTexture=rt;cam.transform.SetPositionAndRotation(p,q);cam.Render();if(name!=null){RenderTexture.active=rt;pic.ReadPixels(new Rect(0,0,w,h),0,0);pic.Apply();File.WriteAllBytes(output+"/"+name,pic.EncodeToPNG());}}finally{cam.targetTexture=target;RenderTexture.active=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(pic);}}
 static void Fail(Exception e){EditorApplication.update-=BakeTick;EditorApplication.update-=CaptureTick;Debug.LogException(e);if(output!=null)File.WriteAllText(output+"/FAILED.txt",e.ToString());EditorApplication.Exit(1);}
}}
